[
    {
        "title": "设未知数",
        "description": "设宿舍有 $n$ 间，新生有 $m$ 人，其中 $n、m$ 均为正整数。",
        "bubbleText": "先用字母表示两个未知量：宿舍间数用 $n$，新生人数用 $m$。",
        "bubblePos": {
            "x": 300.0,
